<?php
declare(strict_types=1);

namespace Sokna\Local\Domain\Sellables;

use PDO;
use PDOException;
use Sokna\Local\Core\IdentityRepository;
use Throwable;

final class CatalogAdminService
{
    private const MENU_STATUSES=['active','draft','inactive'];
    private const AUDIENCES=['guest_staff','staff_only'];
    private const STATIONS=['kitchen','hot_bar','cold_bar','none'];
    private const LIFECYCLES=['active','inactive','retired'];

    public function __construct(
        private readonly PDO $pdo,
        private readonly IdentityRepository $identity,
        private readonly CategoryIconLibrary $icons,
    ){}

    public function snapshot(array $actor): array
    {
        $this->assertAdmin($actor);
        $menus=$this->pdo->query('SELECT id,menu_key,name,status,sort_order,schedule_days,daily_start,daily_end,created_at,updated_at FROM menus ORDER BY sort_order,id')->fetchAll(PDO::FETCH_ASSOC);
        foreach($menus as &$menu){$menu['id']=(int)$menu['id'];$menu['sort_order']=(int)$menu['sort_order'];$menu['schedule_days']=$this->daysFromCsv($menu['schedule_days']??null);}unset($menu);

        $categories=$this->pdo->query("SELECT id,category_key,name,audience,image_path,icon_key,sort_order,active,lifecycle_status,guest_visible,staff_visible,retired_at,retired_note,created_at,updated_at FROM categories WHERE lifecycle_status<>'retired' ORDER BY sort_order,id")->fetchAll(PDO::FETCH_ASSOC);
        $archivedCategories=$this->pdo->query("SELECT id,category_key,name,audience,image_path,icon_key,sort_order,active,lifecycle_status,guest_visible,staff_visible,retired_at,retired_note,created_at,updated_at FROM categories WHERE lifecycle_status='retired' ORDER BY retired_at DESC,id DESC")->fetchAll(PDO::FETCH_ASSOC)?:[];
        $categoryMenus=$this->pdo->query('SELECT category_id,menu_id,sort_order FROM menu_categories ORDER BY category_id,sort_order,menu_id')->fetchAll(PDO::FETCH_ASSOC);
        $categoryMenuMap=[];$categoryMenuSort=[];foreach($categoryMenus as $row){$cid=(int)$row['category_id'];$mid=(int)$row['menu_id'];$categoryMenuMap[$cid][]=$mid;$categoryMenuSort[$cid][(string)$mid]=(int)$row['sort_order'];}
        foreach($categories as &$category){$category=$this->normalizeCategoryRow($category,$categoryMenuMap,$categoryMenuSort);}unset($category);
        foreach($archivedCategories as &$category){$category=$this->normalizeCategoryRow($category,$categoryMenuMap,$categoryMenuSort);}unset($category);

        $items=$this->pdo->query("SELECT i.*,c.name category_name,c.audience category_audience,c.lifecycle_status category_lifecycle_status FROM items i JOIN categories c ON c.id=i.category_id WHERE i.lifecycle_status<>'retired' ORDER BY c.sort_order,c.id,i.sort_order,i.id")->fetchAll(PDO::FETCH_ASSOC);
        $archivedItems=$this->pdo->query("SELECT i.*,c.name category_name,c.audience category_audience,c.lifecycle_status category_lifecycle_status FROM items i JOIN categories c ON c.id=i.category_id WHERE i.lifecycle_status='retired' ORDER BY i.retired_at DESC,i.id DESC")->fetchAll(PDO::FETCH_ASSOC)?:[];
        $itemMenus=$this->pdo->query('SELECT item_id,menu_id FROM menu_items ORDER BY item_id,menu_id')->fetchAll(PDO::FETCH_ASSOC);
        $itemMenuMap=[];foreach($itemMenus as $row)$itemMenuMap[(int)$row['item_id']][]=(int)$row['menu_id'];
        $tags=$this->pdo->query('SELECT id,tag_key,name,active,sort_order,created_at,updated_at FROM catalog_tags ORDER BY sort_order,id')->fetchAll(PDO::FETCH_ASSOC)?:[];
        foreach($tags as &$tag){$tag['id']=(int)$tag['id'];$tag['active']=(int)$tag['active']===1;$tag['sort_order']=(int)$tag['sort_order'];}unset($tag);
        $itemTags=$this->pdo->query('SELECT item_id,tag_id FROM item_tags ORDER BY item_id,tag_id')->fetchAll(PDO::FETCH_ASSOC)?:[];$itemTagMap=[];foreach($itemTags as $row)$itemTagMap[(int)$row['item_id']][]=(int)$row['tag_id'];
        foreach($items as &$item)$item=$this->normalizeItemRow($item,$itemMenuMap,$itemTagMap);unset($item);
        foreach($archivedItems as &$item)$item=$this->normalizeItemRow($item,$itemMenuMap,$itemTagMap);unset($item);

        $families=$this->variantFamiliesSnapshot();
        $suggestions=$this->suggestionsSnapshot();
        $bundles=$this->bundlesSnapshot();

        return [
            'menus'=>$menus,
            'categories'=>$categories,
            'items'=>$items,
            'archived_categories'=>$archivedCategories,
            'archived_items'=>$archivedItems,
            'archive_counts'=>['items'=>count($archivedItems),'categories'=>count($archivedCategories)],
            'variant_families'=>$families,
            'suggestions'=>$suggestions,
            'bundles'=>$bundles,
            'tags'=>$tags,
            'definitions'=>[
                'menu_statuses'=>['active'=>'فعال','draft'=>'پیش‌نویس','inactive'=>'غیرفعال'],
                'audiences'=>['guest_staff'=>'مهمان و کارکنان','staff_only'=>'فقط کارکنان'],
                'lifecycles'=>['active'=>'فعال','inactive'=>'غیرفعال','retired'=>'آرشیو'],
                'sellable_kinds'=>SellableKind::labels(),
                'stations'=>['kitchen'=>'آشپزخانه','hot_bar'=>'بار گرم','cold_bar'=>'بار سرد','none'=>'بدون آماده‌سازی'],
                'days'=>[7=>'شنبه',1=>'یکشنبه',2=>'دوشنبه',3=>'سه‌شنبه',4=>'چهارشنبه',5=>'پنجشنبه',6=>'جمعه'],
                'category_icons'=>$this->icons->groups(),
            ],
            'notes'=>[
                'media'=>'تصویر آیتم از Media Library مدیریت می‌شود؛ آیکن دسته از کتابخانه داخلی امن انتخاب می‌شود.',
                'history'=>'Order snapshots مستقل‌اند؛ تغییر نام/قیمت/نوع آیتم، سفارش‌های گذشته را بازنویسی نمی‌کند.',
            ],
        ];
    }

    public function saveMenu(array $data,array $actor): array
    {
        $admin=$this->assertAdmin($actor);$id=(int)($data['id']??0);$name=$this->text($data['name']??'',120);$status=trim((string)($data['status']??'draft'));$sort=(int)($data['sort_order']??0);
        if($name==='')throw new CatalogAdminException('menu_name','نام منو لازم است.',422);
        if(!in_array($status,self::MENU_STATUSES,true))throw new CatalogAdminException('menu_status','وضعیت منو معتبر نیست.',422);
        [$days,$start,$end]=$this->schedule($data['schedule_days']??[],$data['daily_start']??null,$data['daily_end']??null);
        $this->pdo->beginTransaction();try{
            if($id>0){$q=$this->pdo->prepare('SELECT id,menu_key,name,status FROM menus WHERE id=? FOR UPDATE');$q->execute([$id]);$before=$q->fetch(PDO::FETCH_ASSOC);if(!is_array($before))throw new CatalogAdminException('menu_missing','منو پیدا نشد.',404);$q=$this->pdo->prepare('UPDATE menus SET name=?,status=?,sort_order=?,schedule_days=?,daily_start=?,daily_end=? WHERE id=?');$q->execute([$name,$status,$sort,$days,$start,$end,$id]);$created=false;}
            else{$key=$this->newKey('menus','menu_key');$q=$this->pdo->prepare('INSERT INTO menus(menu_key,name,status,sort_order,schedule_days,daily_start,daily_end) VALUES(?,?,?,?,?,?,?)');$q->execute([$key,$name,$status,$sort,$days,$start,$end]);$id=(int)$this->pdo->lastInsertId();$created=true;}
            $this->audit($created?'catalog.menu_created':'catalog.menu_updated','menu',$id,(int)$admin['id'],['name'=>$name,'status'=>$status,'sort_order'=>$sort,'schedule_days'=>$days,'daily_start'=>$start,'daily_end'=>$end]);
            $this->pdo->commit();return ['id'=>$id];
        }catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }

    public function saveCategory(array $data,array $actor): array
    {
        $admin=$this->assertAdmin($actor);$id=(int)($data['id']??0);$name=$this->text($data['name']??'',120);$audience=trim((string)($data['audience']??'guest_staff'));$sort=(int)($data['sort_order']??0);$lifecycle=$this->currentLifecycle($data['lifecycle_status']??(($data['active']??true)?'active':'inactive'));if($lifecycle==='retired')throw new CatalogAdminException('retire_requires_archive_action','برای انتقال دسته به آرشیو از اقدام آرشیو استفاده کنید.',409);$guestVisible=$this->bool($data['guest_visible']??($audience!=='staff_only'));$staffVisible=$this->bool($data['staff_visible']??true);$active=$lifecycle==='active';$audience=$guestVisible?'guest_staff':'staff_only';$icon=$this->nullableText($data['icon_key']??null,40);$menuIds=$this->intList($data['menu_ids']??[]);
        if($name==='')throw new CatalogAdminException('category_name','نام دسته‌بندی لازم است.',422);
        if(!in_array($audience,self::AUDIENCES,true))throw new CatalogAdminException('category_audience','مخاطب دسته‌بندی معتبر نیست.',422);
        if($icon!==null&&!$this->icons->isAllowed($icon))throw new CatalogAdminException('category_icon','آیکن دسته‌بندی معتبر نیست.',422);
        $this->pdo->beginTransaction();try{
            $this->lockMenus($menuIds);
            if($id>0){$q=$this->pdo->prepare('SELECT id,category_key,name FROM categories WHERE id=? FOR UPDATE');$q->execute([$id]);if(!is_array($q->fetch(PDO::FETCH_ASSOC)))throw new CatalogAdminException('category_missing','دسته‌بندی پیدا نشد.',404);$q=$this->pdo->prepare('UPDATE categories SET name=?,audience=?,icon_key=?,sort_order=?,active=?,lifecycle_status=?,guest_visible=?,staff_visible=? WHERE id=?');$q->execute([$name,$audience,$icon,$sort,$active?1:0,$lifecycle,$guestVisible?1:0,$staffVisible?1:0,$id]);$created=false;}
            else{$key=$this->newKey('categories','category_key');$q=$this->pdo->prepare('INSERT INTO categories(category_key,name,audience,icon_key,sort_order,active,lifecycle_status,guest_visible,staff_visible) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$key,$name,$audience,$icon,$sort,$active?1:0,$lifecycle,$guestVisible?1:0,$staffVisible?1:0]);$id=(int)$this->pdo->lastInsertId();$created=true;}
            $this->setCategoryMenusTx($id,$menuIds);
            $this->audit($created?'catalog.category_created':'catalog.category_updated','category',$id,(int)$admin['id'],['name'=>$name,'audience'=>$audience,'lifecycle_status'=>$lifecycle,'guest_visible'=>$guestVisible,'staff_visible'=>$staffVisible,'sort_order'=>$sort,'menu_ids'=>$menuIds]);
            $this->pdo->commit();return ['id'=>$id];
        }catch(PDOException $e){if($this->pdo->inTransaction())$this->pdo->rollBack();if((int)($e->errorInfo[1]??0)===1062)throw new CatalogAdminException('category_duplicate','شناسه دسته‌بندی تکراری شد؛ دوباره تلاش کن.',409);throw $e;}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }

    public function saveItem(array $data,array $actor): array
    {
        $admin=$this->assertAdmin($actor);$id=(int)($data['id']??0);$name=$this->text($data['name']??'',160);$description=$this->nullableText($data['description']??null,2000);$price=$this->amount($data['price']??null);$categoryId=(int)($data['category_id']??0);$kind=SellableKind::requireWrite($data['sellable_kind']??SellableKind::MENU_ITEM);$station=$this->normalizeStation((string)($data['preparation_station']??'cold_bar'));$sort=(int)($data['sort_order']??0);$lifecycle=$this->currentLifecycle($data['lifecycle_status']??(($data['active']??true)?'active':'inactive'));if($lifecycle==='retired')throw new CatalogAdminException('retire_requires_archive_action','برای انتقال آیتم به آرشیو از اقدام آرشیو استفاده کنید.',409);$available=$lifecycle==='active'&&$this->bool($data['available']??true);$guestVisible=$this->bool($data['guest_visible']??!$this->bool($data['staff_only']??false));$staffVisible=$this->bool($data['staff_visible']??true);$active=$lifecycle==='active';$featured=$this->bool($data['featured']??false);$staffOnly=!$guestVisible;$takeaway=$this->bool($data['takeaway_allowed']??true);$menuIds=$this->intList($data['menu_ids']??[]);$tagIds=$this->intList($data['tag_ids']??[]);
        [$days,$dailyStart,$dailyEnd]=$this->schedule($data['schedule_days']??[],$data['daily_start']??null,$data['daily_end']??null);$scheduleStart=$this->dateTime($data['schedule_start']??null);$scheduleEnd=$this->dateTime($data['schedule_end']??null);if($scheduleStart!==null&&$scheduleEnd!==null&&$scheduleStart>$scheduleEnd)throw new CatalogAdminException('item_schedule_range','پایان بازه آیتم باید بعد از شروع باشد.',422);
        if($name===''||$categoryId<1)throw new CatalogAdminException('item_required','نام و دسته‌بندی آیتم لازم است.',422);
        $this->pdo->beginTransaction();try{
            $q=$this->pdo->prepare('SELECT id,lifecycle_status FROM categories WHERE id=? FOR UPDATE');$q->execute([$categoryId]);$categoryRow=$q->fetch(PDO::FETCH_ASSOC);if(!is_array($categoryRow)||(string)($categoryRow['lifecycle_status']??'active')==='retired')throw new CatalogAdminException('category_missing','دسته‌بندی انتخاب‌شده پیدا نشد یا در آرشیو است.',422);
            $allowed=$this->categoryMenuIdsTx($categoryId);if(array_diff($menuIds,$allowed))throw new CatalogAdminException('item_menu_boundary','یکی از منوهای انتخاب‌شده برای این دسته‌بندی مجاز نیست.',422,['allowed_menu_ids'=>$allowed]);
            if($id>0){$q=$this->pdo->prepare('SELECT id,item_code,image_path FROM items WHERE id=? FOR UPDATE');$q->execute([$id]);$before=$q->fetch(PDO::FETCH_ASSOC);if(!is_array($before))throw new CatalogAdminException('item_missing','آیتم پیدا نشد.',404);$q=$this->pdo->prepare('UPDATE items SET category_id=?,name=?,description=?,price=?,available=?,active=?,lifecycle_status=?,guest_visible=?,staff_visible=?,featured=?,staff_only=?,sellable_kind=?,takeaway_allowed=?,preparation_station=?,schedule_start=?,schedule_end=?,schedule_days=?,daily_start=?,daily_end=?,sort_order=? WHERE id=?');$q->execute([$categoryId,$name,$description,$price,$available?1:0,$active?1:0,$lifecycle,$guestVisible?1:0,$staffVisible?1:0,$featured?1:0,$staffOnly?1:0,$kind,$takeaway?1:0,$station,$scheduleStart,$scheduleEnd,$days,$dailyStart,$dailyEnd,$sort,$id]);$created=false;}
            else{$q=$this->pdo->prepare('INSERT INTO items(item_code,category_id,name,description,price,available,active,lifecycle_status,guest_visible,staff_visible,featured,staff_only,sellable_kind,takeaway_allowed,preparation_station,schedule_start,schedule_end,schedule_days,daily_start,daily_end,sort_order) VALUES(NULL,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$categoryId,$name,$description,$price,$available?1:0,$active?1:0,$lifecycle,$guestVisible?1:0,$staffVisible?1:0,$featured?1:0,$staffOnly?1:0,$kind,$takeaway?1:0,$station,$scheduleStart,$scheduleEnd,$days,$dailyStart,$dailyEnd,$sort]);$id=(int)$this->pdo->lastInsertId();$this->pdo->prepare('UPDATE items SET item_code=? WHERE id=?')->execute(['ITEM-'.$id,$id]);$created=true;}
            $this->setItemMenusTx($id,$menuIds);$this->setItemTagsTx($id,$tagIds);
            $this->audit($created?'catalog.item_created':'catalog.item_updated','menu_item',$id,(int)$admin['id'],['name'=>$name,'category_id'=>$categoryId,'price'=>$price,'sellable_kind'=>$kind,'available'=>$available,'lifecycle_status'=>$lifecycle,'guest_visible'=>$guestVisible,'staff_visible'=>$staffVisible,'featured'=>$featured,'takeaway_allowed'=>$takeaway,'preparation_station'=>$station,'menu_ids'=>$menuIds,'tag_ids'=>$tagIds]);
            $this->pdo->commit();return ['id'=>$id];
        }catch(PDOException $e){if($this->pdo->inTransaction())$this->pdo->rollBack();if((int)($e->errorInfo[1]??0)===1062)throw new CatalogAdminException('item_duplicate','شناسه داخلی آیتم تکراری شد؛ دوباره تلاش کن.',409);throw $e;}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }

    public function saveTag(array $data,array $actor): array
    {
        $admin=$this->assertAdmin($actor);$id=(int)($data['id']??0);$name=$this->text($data['name']??'',120);$active=$this->bool($data['active']??true);$sort=(int)($data['sort_order']??0);
        if($name==='')throw new CatalogAdminException('tag_name','نام برچسب لازم است.',422);
        $this->pdo->beginTransaction();try{
            if($id>0){$q=$this->pdo->prepare('SELECT id FROM catalog_tags WHERE id=? FOR UPDATE');$q->execute([$id]);if(!$q->fetchColumn())throw new CatalogAdminException('tag_missing','برچسب پیدا نشد.',404);$this->pdo->prepare('UPDATE catalog_tags SET name=?,active=?,sort_order=? WHERE id=?')->execute([$name,$active?1:0,$sort,$id]);$created=false;}
            else{$key=$this->newKey('catalog_tags','tag_key');$this->pdo->prepare('INSERT INTO catalog_tags(tag_key,name,active,sort_order) VALUES(?,?,?,?)')->execute([$key,$name,$active?1:0,$sort]);$id=(int)$this->pdo->lastInsertId();$created=true;}
            $this->audit($created?'catalog.tag_created':'catalog.tag_updated','catalog_tag',$id,(int)$admin['id'],['name'=>$name,'active'=>$active,'sort_order'=>$sort]);$this->pdo->commit();return ['id'=>$id];
        }catch(PDOException $e){if($this->pdo->inTransaction())$this->pdo->rollBack();if((int)($e->errorInfo[1]??0)===1062)throw new CatalogAdminException('tag_duplicate','برچسبی با این نام وجود دارد.',409);throw $e;}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }

    public function copyItem(int $id,array $actor): array
    {
        $admin=$this->assertAdmin($actor);if($id<1)throw new CatalogAdminException('item_invalid','آیتم معتبر نیست.',422);
        $this->pdo->beginTransaction();try{
            $q=$this->pdo->prepare('SELECT * FROM items WHERE id=? FOR UPDATE');$q->execute([$id]);$row=$q->fetch(PDO::FETCH_ASSOC);if(!is_array($row))throw new CatalogAdminException('item_missing','آیتم پیدا نشد.',404);
            $name=$this->text((string)$row['name'].' — کپی',160);
            $ins=$this->pdo->prepare('INSERT INTO items(item_code,category_id,name,description,price,image_path,available,active,lifecycle_status,guest_visible,staff_visible,featured,staff_only,sellable_kind,takeaway_allowed,preparation_station,schedule_start,schedule_end,schedule_days,daily_start,daily_end,suggested_item_id,sort_order) VALUES(NULL,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');
            $ins->execute([(int)$row['category_id'],$name,$row['description'],$row['price'],$row['image_path'],0,0,'inactive',0,0,(int)$row['featured'],1,$row['sellable_kind'],(int)$row['takeaway_allowed'],$row['preparation_station'],$row['schedule_start'],$row['schedule_end'],$row['schedule_days'],$row['daily_start'],$row['daily_end'],$row['suggested_item_id'],(int)$row['sort_order']+10]);
            $newId=(int)$this->pdo->lastInsertId();$this->pdo->prepare('UPDATE items SET item_code=? WHERE id=?')->execute(['ITEM-'.$newId,$newId]);
            $menus=$this->itemMenuIdsTx($id);$this->setItemMenusTx($newId,$menus);$tags=$this->itemTagIdsTx($id);$this->setItemTagsTx($newId,$tags);
            if(str_starts_with((string)($row['image_path']??''),'media:')){$key=substr((string)$row['image_path'],6);$mq=$this->pdo->prepare('SELECT id FROM guest_media_assets WHERE media_key=? AND active=1');$mq->execute([$key]);$mid=(int)($mq->fetchColumn()?:0);if($mid>0)$this->pdo->prepare("INSERT IGNORE INTO guest_media_references(media_id,owner_type,owner_id,slot_key) VALUES(?,'item',?,'card')")->execute([$mid,(string)$newId]);}
            $this->audit('catalog.item_copied','menu_item',$newId,(int)$admin['id'],['source_item_id'=>$id,'name'=>$name]);$this->pdo->commit();return ['id'=>$newId];
        }catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }

    public function bulkUpdateItems(array $data,array $actor): array
    {
        $admin=$this->assertAdmin($actor);$ids=$this->intList($data['ids']??[]);if($ids===[])throw new CatalogAdminException('bulk_items','حداقل یک آیتم انتخاب کن.',422);
        $field=(string)($data['field']??'');$allowed=['available','featured','guest_visible','staff_visible'];if(!in_array($field,$allowed,true))throw new CatalogAdminException('bulk_field','عملیات گروهی معتبر نیست.',422);$enabled=$this->bool($data['enabled']??false);
        $ph=implode(',',array_fill(0,count($ids),'?'));$this->pdo->beginTransaction();try{$q=$this->pdo->prepare("SELECT id,lifecycle_status FROM items WHERE id IN($ph) FOR UPDATE");$q->execute($ids);$rows=$q->fetchAll(PDO::FETCH_ASSOC);$found=array_map(static fn(array $row):int=>(int)$row['id'],$rows);if(count($found)!==count($ids))throw new CatalogAdminException('item_missing','یکی از آیتم‌های انتخاب‌شده پیدا نشد.',404);if($field==='available'&&$enabled){$blocked=array_values(array_filter($rows,static fn(array $row):bool=>(string)($row['lifecycle_status']??'active')!=='active'));if($blocked!==[])throw new CatalogAdminException('item_inactive','برای موجود کردن گروهی، همه آیتم‌های انتخاب‌شده باید فعال باشند.',409);}$sql='UPDATE items SET '.$field.'=? WHERE id IN('.$ph.')';$u=$this->pdo->prepare($sql);$u->execute(array_merge([$enabled?1:0],$ids));$this->audit('catalog.items_bulk_updated','menu_item',0,(int)$admin['id'],['ids'=>$ids,'field'=>$field,'enabled'=>$enabled]);$this->pdo->commit();return ['ids'=>$ids,'field'=>$field,'enabled'=>$enabled,'changed'=>$u->rowCount()];}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }

    public function reorderCategoriesForMenu(int $menuId,array $orderedIds,array $actor): array
    {
        $admin=$this->assertAdmin($actor);if($menuId<1)throw new CatalogAdminException('menu_missing','منو معتبر نیست.',422);$ids=$this->intList($orderedIds??[]);$this->pdo->beginTransaction();try{$q=$this->pdo->prepare('SELECT category_id FROM menu_categories WHERE menu_id=? ORDER BY sort_order,category_id FOR UPDATE');$q->execute([$menuId]);$current=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));$a=$current;$b=$ids;sort($a);sort($b);if($a!==$b)throw new CatalogAdminException('category_reorder_set','فهرست دسته‌ها با عضویت این منو یکسان نیست.',409);$u=$this->pdo->prepare('UPDATE menu_categories SET sort_order=? WHERE menu_id=? AND category_id=?');foreach($ids as $idx=>$cid)$u->execute([($idx+1)*10,$menuId,$cid]);$this->audit('catalog.categories_reordered','menu',$menuId,(int)$admin['id'],['category_ids'=>$ids]);$this->pdo->commit();return ['menu_id'=>$menuId,'category_ids'=>$ids];}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }

    public function reorderItemsForCategory(int $categoryId,array $orderedIds,array $actor): array
