        foreach($components as $row){if(!is_array($row))continue;$itemId=(int)($row['component_item_id']??0);$mode=(string)($row['mode']??'fixed');$qty=max(1,min(100,(int)($row['quantity']??1)));$delta=(int)($row['price_delta']??0);if($itemId<1||$itemId===$bundleItemId||!in_array($mode,['fixed','choice'],true))throw new CatalogAdminException('bundle_component_invalid','جزء ترکیب معتبر نیست.',422);$key=$itemId.':'.$mode;if(isset($norm[$key]))throw new CatalogAdminException('bundle_component_duplicate','جزء تکراری در ترکیب وجود دارد.',409);$norm[$key]=['component_item_id'=>$itemId,'mode'=>$mode,'quantity'=>$qty,'price_delta'=>$delta,'sort_order'=>(int)($row['sort_order']??((count($norm)+1)*10))];if($mode==='choice')$choice++;}
