        $this->pdo->beginTransaction();try{$ids=array_values(array_unique(array_merge([$bundleItemId],array_column($norm,'component_item_id'))));$ph=implode(',',array_fill(0,count($ids),'?'));$q=$this->pdo->prepare("SELECT i.id,i.lifecycle_status,i.guest_visible,i.staff_visible,EXISTS(SELECT 1 FROM item_bundles b WHERE b.bundle_item_id=i.id) is_bundle FROM items i WHERE i.id IN($ph) FOR UPDATE");$q->execute($ids);$rows=$q->fetchAll(PDO::FETCH_ASSOC);if(count($rows)!==count($ids))throw new CatalogAdminException('bundle_item_missing','یکی از آیتم‌های ترکیب پیدا نشد.',404);$byId=[];foreach($rows as $r)$byId[(int)$r['id']]=$r;$parent=$byId[$bundleItemId]??null;if(!is_array($parent)||((string)$parent['lifecycle_status']==='retired'))throw new CatalogAdminException('bundle_parent_invalid','آیتم اصلی ترکیب معتبر نیست.',409);foreach($rows as $r){$rid=(int)$r['id'];if($rid===$bundleItemId)continue;if((string)$r['lifecycle_status']!=='active')throw new CatalogAdminException('bundle_component_inactive','جزء ترکیب باید در کاتالوگ فعال باشد.',409);if((int)$r['is_bundle']===1)throw new CatalogAdminException('nested_bundle','ترکیب تو در تو مجاز نیست.',409);if((int)$parent['guest_visible']===1&&(int)$r['guest_visible']!==1)throw new CatalogAdminException('bundle_guest_visibility','جزء ترکیب مهمان باید برای مهمان قابل نمایش باشد.',409);if((int)$parent['staff_visible']===1&&(int)$r['staff_visible']!==1)throw new CatalogAdminException('bundle_staff_visibility','جزء ترکیب کارکنان باید برای کارکنان قابل نمایش باشد.',409);}$this->pdo->prepare('INSERT INTO item_bundles(bundle_item_id,choice_label,choice_min,choice_max) VALUES(?,?,1,1) ON DUPLICATE KEY UPDATE choice_label=VALUES(choice_label),choice_min=1,choice_max=1')->execute([$bundleItemId,$choiceLabel]);$this->pdo->prepare('DELETE FROM item_bundle_components WHERE bundle_item_id=?')->execute([$bundleItemId]);$ins=$this->pdo->prepare('INSERT INTO item_bundle_components(bundle_item_id,component_item_id,mode,quantity,price_delta,sort_ord