    private function normalizeCategoryRow(array $category,array $menuMap,array $sortMap): array
    {
        $category['id']=(int)$category['id'];$category['sort_order']=(int)$category['sort_order'];foreach(['active','guest_visible','staff_visible'] as $flag)$category[$flag]=(int)($category[$flag]??0)===1;$category['lifecycle_status']=(string)($category['lifecycle_status']??($category['active']?'active':'inactive'));$category['menu_ids']=$menuMap[$category['id']]??[];$category['menu_sort_orders']=$sortMap[$category['id']]??[];return $category;
    }
    private function normalizeItemRow(array $item,array $menuMap,array $tagMap): array
    {
        $item['id']=(int)$item['id'];$item['category_id']=(int)$item['category_id'];$item['price']=(int)$item['price'];$item['sort_order']=(int)$item['sort_order'];foreach(['available','active','guest_visible','staff_visible','featured','staff_only','takeaway_allowed'] as $flag)$item[$flag]=(int)($item[$flag]??0)===1;$item['lifecycle_status']=(string)($item['lifecycle_status']??($item['active']?'active':'inactive'));$item['sellable_kind']=SellableKind::normalizeRead($item['sellable_kind']??null);$item['sellable_kind_label']=SellableKind::label($item['sellable_kind']);$item['preparation_station']=$this->normalizeStation((string)($item['preparation_station']??'cold_bar'));$item['schedule_days']=$this->daysFromCsv($item['schedule_days']??null);$item['menu_ids']=$menuMap[$item['id']]??[];$item['tag_ids']=$tagMap[$item['id']]??[];return $item;
    }
    private function currentLifecycle(mixed $value): string
