    private function csvDays(mixed $days): ?string{$list=$this->intList(is_array($days)?$days:($days===null?[]:explode(',',(string)$days)),1,7);sort($list);return $list?implode(',',$list):null;}

    private function assertAdmin(array $user): array{$id=(int)($user['id']??0);if($id<1)throw new CatalogAdminException('forbidden','حساب معتبر نیست.',403);$fresh=$this->identity->findActiveById($id);if($fresh===null||(string)($fresh['role']??'')!=='admin')throw new CatalogAdminException('forbidden','مدیریت کاتالوگ فقط برای مدیر فعال است.',403);return $fresh;}
    private function lockMenus(array $ids): void{if($ids===[])return;$ph=implode(',',array_fill(0,count($ids),'?'));$q=$this->pdo->prepare("SELECT id FROM menus WHERE id IN($ph) FOR UPDATE");$q->execute($ids);$found=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));sort($found);$expected=$ids;sort($expected);if($found!==$expected)throw new CatalogAdminException('menu_missing','یکی از منوهای انتخاب‌شده پیدا نشد.',422);}
    private function setCategoryMenusTx(int $categoryId,array $menuIds): void{$this->lockMenus($menuIds);$oldQ=$this->pdo->prepare('SELECT menu_id,sort_order FROM menu_categories WHERE category_id=? FOR UPDATE');$oldQ->execute([$categoryId]);$old=[];foreach($oldQ->fetchAll(PDO::FETCH_ASSOC) as $r)$old[(int)$r['menu_id']]=(int)$r['sort_order'];$this->pdo->prepare('DELETE FROM menu_categories WHERE category_id=?')->execute([$categoryId]);if($menuIds!==[]){$ins=$this->pdo->prepare('INSERT INTO menu_categories(menu_id,category_id,sort_order) VALUES(?,?,?)');$maxQ=$this->pdo->prepare('SELECT COALESCE(MAX(sort_order),0) FROM menu_categories WHERE menu_id=?');foreach($menuIds as $menuId){if(isset($old[$menuId]))$sort=$old[$menuId];else{$maxQ->execute([$menuId]);$sort=(int)$maxQ->fetchColumn()+10;}$ins->execute([$menuId,$categoryId,$sort]);}}$allowed=$menuIds;$q=$this->pdo->prepare('SELECT id FROM items WHERE category_id=?');$q->execute([$categoryId]);foreach(array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN)) as $itemId){$current=$this->itemMenuIdsTx($itemId);$keep=array_values(array_intersect($current,$allowed));$this->setItemMenusTx($itemId,$keep);}}
    private function setItemMenusTx(int $itemId,array $menuIds): void{$this->pdo->prepare('DELETE FROM menu_items WHERE item_id=?')->execute([$itemId]);if($menuIds!==[]){$ins=$this->pdo->prepare('INSERT INTO menu_items(menu_id,item_id) VALUES(?,?)');foreach($menuIds as $menuId)$ins->execute([$menuId,$itemId]);}}
